import{_ as a,o as e,c as n,a2 as s}from"./chunks/framework.A5mep7Fe.js";const c=JSON.parse('{"title":"🛡️ 05 · Agent 工程化与评估（从 Demo 到生产）","description":"","frontmatter":{},"headers":[],"relativePath":"03-算法岗-AI-Agent/05-Agent工程化与评估.md","filePath":"03-算法岗-AI-Agent/05-Agent工程化与评估.md","lastUpdated":1786806808000}'),o={name:"03-算法岗-AI-Agent/05-Agent工程化与评估.md"};function r(l,t,i,d,g,h){return e(),n("div",null,[...t[0]||(t[0]=[s(`<h1 id="🛡️-05-·-agent-工程化与评估-从-demo-到生产" tabindex="-1">🛡️ 05 · Agent 工程化与评估（从 Demo 到生产） <a class="header-anchor" href="#🛡️-05-·-agent-工程化与评估-从-demo-到生产" aria-label="Permalink to &quot;🛡️ 05 · Agent 工程化与评估（从 Demo 到生产）&quot;">​</a></h1><blockquote><p>面试区分度极高的话题：<strong>能跑 demo 的人很多，能上生产的人很少。</strong> 本篇讲可靠性、可观测、成本控制与评测。</p></blockquote><hr><h2 id="一、可靠性工程" tabindex="-1">一、可靠性工程 <a class="header-anchor" href="#一、可靠性工程" aria-label="Permalink to &quot;一、可靠性工程&quot;">​</a></h2><ul><li><strong>超时与降级</strong>：工具调用超时 → 重试/备用/降级回答，绝不卡死。</li><li><strong>重试与指数退避</strong>：对瞬时失败（API 限流）重试，避免雪崩。</li><li><strong>熔断（Circuit Breaker）</strong>：某工具/模型连续失败 → 暂时停用，保护系统。</li><li><strong>最大步数/循环检测</strong>：防 Agent 无限循环，超步数强制终止并说明。</li><li><strong>输入/输出校验</strong>：工具参数 schema 校验；模型输出格式校验（JSON mode / 结构化）。</li></ul><hr><h2 id="二、可观测性-observability" tabindex="-1">二、可观测性（Observability） <a class="header-anchor" href="#二、可观测性-observability" aria-label="Permalink to &quot;二、可观测性（Observability）&quot;">​</a></h2><ul><li><strong>全链路追踪</strong>：记录每步 Thought/Action/Observation、token 消耗、耗时、调用链。</li><li><strong>日志与回放</strong>：出问题能回放整条轨迹定位（LangSmith / 自研 trace）。</li><li><strong>评测数据集</strong>：固化一批典型 case，每次改动能回归测试。</li></ul><hr><h2 id="三、成本控制" tabindex="-1">三、成本控制 <a class="header-anchor" href="#三、成本控制" aria-label="Permalink to &quot;三、成本控制&quot;">​</a></h2><ul><li><strong>模型路由</strong>：简单任务用小模型，复杂任务才上大模型（如分类用 0.5B，推理用 70B）。</li><li><strong>缓存</strong>：相同 query 缓存结果；语义缓存（相似问题复用）。</li><li><strong>上下文压缩</strong>：去掉无关历史，省 token。</li><li><strong>批处理 / 异步</strong>：并发降低延迟与成本。</li></ul><hr><h2 id="四、agent-评估体系" tabindex="-1">四、Agent 评估体系 <a class="header-anchor" href="#四、agent-评估体系" aria-label="Permalink to &quot;四、Agent 评估体系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>评测什么</th><th>方法</th></tr></thead><tbody><tr><td>单工具</td><td>工具调用正确率、参数准确</td><td>单元测试</td></tr><tr><td>轨迹</td><td>步骤是否合理、是否走偏</td><td>人工/Trajectory 评测</td></tr><tr><td>结果</td><td>最终答案是否正确可用</td><td>任务成功率、LLM-as-Judge</td></tr><tr><td>系统</td><td>延迟、成本、可靠性</td><td>线上监控 + AB</td></tr></tbody></table><p>常用基准：AgentBench、WebArena、ToolBench、GAIA。</p><hr><h2 id="五、部署架构-典型" tabindex="-1">五、部署架构（典型） <a class="header-anchor" href="#五、部署架构-典型" aria-label="Permalink to &quot;五、部署架构（典型）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户请求 → API 网关 → 意图识别 → Agent 编排器</span></span>
<span class="line"><span>                              ├── ReAct Agent（思考-行动-观察）</span></span>
<span class="line"><span>                              ├── 规划 Agent（任务分解）</span></span>
<span class="line"><span>                              ├── RAG Agent（知识检索）</span></span>
<span class="line"><span>                              └── 反思 Agent（质量校验）</span></span>
<span class="line"><span>支撑层：多路检索(向量+BM25) · 记忆(Redis滑窗+向量库) ·</span></span>
<span class="line"><span>       工具系统(MCP) · 模型路由+熔断 · 全链路追踪 · 文档ETL</span></span></code></pre></div><hr><h2 id="六、高频追问" tabindex="-1">六、高频追问 <a class="header-anchor" href="#六、高频追问" aria-label="Permalink to &quot;六、高频追问&quot;">​</a></h2><p><strong>Q1：Agent 上线最大的坑是什么？</strong></p><blockquote><p>不可控性：长链路任一步失败/幻觉都影响结果；成本高且难预测；难评测。解法：全链路追踪 + 降级 + 回归评测集 + 成本监控。</p></blockquote><p><strong>Q2：怎么做 Agent 的回归测试？</strong></p><blockquote><p>固化典型任务集与「期望轨迹/结果」，每次改动跑回归；用 LLM-as-Judge 评质量；监控线上成功率/成本/延迟漂移。</p></blockquote><p><strong>Q3：模型路由怎么设计？</strong></p><blockquote><p>按任务复杂度路由：分类/抽取用小模型，推理/生成用大模型；用置信度/失败率动态调整；保证整体成本与质量平衡。</p></blockquote><hr><p>➡️ 返回：<a href="./README">03-算法岗-AI-Agent README</a> ｜ 进入：<a href="./../04-算法岗-传统深度学习/README">04-算法岗-传统深度学习</a></p>`,28)])])}const u=a(o,[["render",r]]);export{c as __pageData,u as default};
